const staticData = $getWorkflowStaticData('global');
staticData.campaigns = [];
staticData.adsets = {};
staticData.account_counts = {};
staticData.ab_by_campaign = {};
const rows = $input.first().json;
const arr = Array.isArray(rows) ? rows : (rows.data || []);
const saMap = {};
for (const r of arr) saMap[r.audience_id] = r.kind;
staticData.saMap = saMap;
return [{ json: { sa_count: arr.length } }];

return [
  { json: { account_id: 'act_10201019819851931', label: 'Account 1' } },
  { json: { account_id: 'act_708812601077037',  label: 'Account 2' } },
  { json: { account_id: 'act_293603336988341',  label: 'Account 3' } },
  { json: { account_id: 'act_3684421665103341', label: 'Account 4' } },
  { json: { account_id: 'act_249137098153238',  label: 'Account 5' } },
  { json: { account_id: 'act_1738224836936889', label: 'Account 6' } },
  { json: { account_id: 'act_1093083055897528', label: 'Account 7' } }
];

const account = $('Loop Accounts').item.json;
const pages = $input.all();
const staticData = $getWorkflowStaticData('global');
staticData.campaigns = staticData.campaigns || [];
staticData.ab_by_campaign = staticData.ab_by_campaign || {};
staticData.account_counts = staticData.account_counts || {};
staticData.account_counts[account.account_id] = staticData.account_counts[account.account_id] || { A: 0, B: 0 };

for (const p of pages) {
  const data = Array.isArray(p.json.data) ? p.json.data : [];
  for (const c of data) {
    if (!c.name) continue;
    const hasA = /\(A\)/.test(c.name);
    const hasB = /\(B\)/.test(c.name);
    if (!hasA && !hasB) continue;
    const tag = hasA ? 'A' : 'B';
    staticData.account_counts[account.account_id][tag]++;
    const row = { account_id: account.account_id, campaign_id: c.id, campaign_name: c.name, tag, status: c.status, effective_status: c.effective_status };
    staticData.campaigns.push(row);
    staticData.ab_by_campaign[c.id] = row;
  }
}

return [{ json: { account_id: account.account_id, ab_campaigns: Object.keys(staticData.ab_by_campaign).filter(k => staticData.ab_by_campaign[k].account_id === account.account_id).length }, pairedItem: { item: 0 } }];

// Classifier matches clinic-manager FB targeting export pattern:
//   drive_time = many small inclusion circles (<=5mi) AND >=4 large exclusion circles (>=20mi)
// Anything else with custom_locations but not matching the pattern = legacy_partial_pattern
// 1-3 circles, no exclusions = legacy_simple_radius
// city/zip/region = legacy_geo_classic
const account = $('Loop Accounts').item.json;
const pages = $input.all();
const staticData = $getWorkflowStaticData('global');
const saMap = staticData.saMap || {};
const ab = staticData.ab_by_campaign || {};
staticData.adsets = staticData.adsets || {};

function classify(t) {
  if (!t) return { kind: 'no_targeting', smallIncl: 0, largeExcl: 0, totalIncl: 0, totalExcl: 0, hasCities: false, hasZips: false, hasRegions: false };
  const geo = t.geo_locations || {};
  const exGeo = t.excluded_geo_locations || {};
  const incl = Array.isArray(geo.custom_locations) ? geo.custom_locations : [];
  const excl = Array.isArray(exGeo.custom_locations) ? exGeo.custom_locations : [];
  const cities = Array.isArray(geo.cities) ? geo.cities.length : 0;
  const zips = Array.isArray(geo.zips) ? geo.zips.length : 0;
  const regions = Array.isArray(geo.regions) ? geo.regions.length : 0;
  const meta = { totalIncl: incl.length, totalExcl: excl.length, hasCities: cities > 0, hasZips: zips > 0, hasRegions: regions > 0,
    smallIncl: incl.filter(p => (p.radius != null ? p.radius : 99) <= 5).length,
    largeExcl: excl.filter(p => (p.radius != null ? p.radius : 0) >= 20).length };
  if (cities || zips || regions) return Object.assign({ kind: 'legacy_geo_classic' }, meta);
  if (incl.length === 0) return Object.assign({ kind: 'no_geo' }, meta);
  if (meta.smallIncl >= 5 && meta.largeExcl >= 4) return Object.assign({ kind: 'drive_time' }, meta);
  if (incl.length <= 3 && excl.length === 0) return Object.assign({ kind: 'legacy_simple_radius' }, meta);
  return Object.assign({ kind: 'legacy_partial_pattern' }, meta);
}

let adsetsSeen = 0;
let adsetsKept = 0;
let errPages = 0;
staticData.errors = staticData.errors || [];
for (const p of pages) {
  if (p.json && p.json.error) { errPages++; staticData.errors.push({account: account.account_id, err: p.json.error.message || JSON.stringify(p.json.error).slice(0,200)}); continue; }
  if (!Array.isArray(p.json && p.json.data)) { errPages++; staticData.errors.push({account: account.account_id, err: 'no_data_field', sample: JSON.stringify(p.json).slice(0,300)}); continue; }
  const data = p.json.data;
  for (const a of data) {
    adsetsSeen++;
    const camp = ab[a.campaign_id];
    if (!camp) continue;
    adsetsKept++;
    const said = a.saved_audience_id || null;
    const c = classify(a.targeting);
    let kind = c.kind;
    if (said) {
      const fromInventory = saMap[said];
      kind = fromInventory === 'drive_time' ? 'drive_time' : ('sa_' + (fromInventory || 'unknown'));
    }
    staticData.adsets[a.id] = {
      account_id: camp.account_id,
      campaign_id: camp.campaign_id,
      campaign_name: camp.campaign_name,
      tag: camp.tag,
      adset_id: a.id,
      adset_name: a.name,
      adset_effective: a.effective_status,
      saved_audience_id: said,
      small_incl_count: c.smallIncl,
      large_excl_count: c.largeExcl,
      total_incl_count: c.totalIncl,
      total_excl_count: c.totalExcl,
      has_cities: c.hasCities,
      has_zips: c.hasZips,
      has_regions: c.hasRegions,
      kind
    };
  }
}
return [{ json: { account_id: account.account_id, adsets_seen: adsetsSeen, adsets_kept: adsetsKept, errored_pages: errPages, total_classified: Object.keys(staticData.adsets).length }, pairedItem: { item: 0 } }];

// Build a single item containing the adset rows array as a JSON string.
const staticData = $getWorkflowStaticData('global');
const adsets = staticData.adsets || {};
const now = new Date().toISOString();
const rows = [];
for (const ad of Object.values(adsets)) {
  rows.push({ ...ad, audited_at: now });
}
return [{ json: { row_count: rows.length, body: JSON.stringify(rows) } }];

const staticData = $getWorkflowStaticData('global');
const campaigns = staticData.campaigns || [];
const adsets = staticData.adsets || {};
const kindCounts = {};
for (const ad of Object.values(adsets)) kindCounts[ad.kind] = (kindCounts[ad.kind] || 0) + 1;
const byAccountKind = {};
for (const ad of Object.values(adsets)) {
  byAccountKind[ad.account_id] = byAccountKind[ad.account_id] || {};
  byAccountKind[ad.account_id][ad.kind] = (byAccountKind[ad.account_id][ad.kind] || 0) + 1;
}
let dt = 0, notDt = 0;
for (const [k, n] of Object.entries(kindCounts)) { if (k === 'drive_time') dt += n; else notDt += n; }

staticData.campaigns = [];
staticData.adsets = {};
staticData.account_counts = {};
staticData.ab_by_campaign = {};
staticData.saMap = {};

const errors = staticData.errors || [];
staticData.errors = [];
return [{ json: {
  total_AB_campaigns: campaigns.length,
  total_adsets: Object.keys(adsets).length,
  drive_time_adsets: dt,
  legacy_adsets: notDt,
  by_kind: kindCounts,
  by_account_kind: byAccountKind,
  error_count: errors.length,
  error_samples: errors.slice(0, 10),
  persisted: true
}}];
